/**
 * ArcenEmbed — Embeddable customer billing portal component.
 *
 * Drop this into your customer-facing app to give users a self-serve
 * billing portal. Uses a short-lived access token generated by your backend.
 *
 * Features rendered (based on component config from dashboard):
 *  - Plan Manager: current plan + upgrade/downgrade buttons
 *  - Included Features: list of features in current plan
 *  - Metered Features: usage progress bars (e.g., 3/50 scans used)
 *  - Plans Table: full plan comparison grid
 *
 * @example
 * <ArcenEmbed
 *   accessToken={tokenFromBackend}
 *   componentId="cmpn_xxx"
 *   baseUrl="https://dashboard.arcenpay.xyz"
 * />
 */

"use client";

import React, { useEffect, useState } from "react";
import type { ComponentRenderData } from "@meap/core";

interface ArcenEmbedProps {
  accessToken: string;
  componentId: string;
  baseUrl?: string;
  className?: string;
  style?: React.CSSProperties;
  /** Called when user successfully upgrades/downgrades */
  onPlanChange?: (planId: string) => void;
}

function MeteredFeatureBar({
  name,
  used,
  limit,
  unitPlural,
}: {
  name: string;
  used: number;
  limit?: number;
  unitPlural: string | null;
}) {
  const pct = limit ? Math.min((used / limit) * 100, 100) : 0;
  return (
    <div style={{ marginBottom: 12 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginBottom: 4,
          fontSize: 13,
        }}
      >
        <span>{name}</span>
        <span style={{ color: "#888888" }}>
          {used}
          {limit ? ` / ${limit}` : ""} {unitPlural ?? "uses"}
        </span>
      </div>
      {limit && (
        <div style={{ height: 6, background: "#e5e7eb", borderRadius: 3 }}>
          <div
            style={{
              height: 6,
              width: `${pct}%`,
              background:
                pct >= 90 ? "#ef4444" : pct >= 70 ? "#f59e0b" : "#e8e8e8",
              borderRadius: 3,
              transition: "width 0.3s ease",
            }}
          />
        </div>
      )}
    </div>
  );
}

function PlanCard({
  plan,
  isActive,
  onSelect,
}: {
  plan: {
    id: string;
    name: string;
    tier: string;
    price: string;
    billingInterval: number;
  };
  isActive: boolean;
  onSelect?: (planId: string) => void;
}) {
  const priceNum = parseFloat(plan.price);
  const interval =
    plan.billingInterval === 2592000
      ? "/mo"
      : plan.billingInterval === 31536000
        ? "/yr"
        : "";
  return (
    <div
      style={{
        border: `2px solid ${isActive ? "#e8e8e8" : "rgba(255,255,255,0.08)"}`,
        borderRadius: 8,
        padding: 16,
        flex: 1,
        minWidth: 160,
        background: isActive
          ? "rgba(255,255,255,0.06)"
          : "rgba(255,255,255,0.03)",
      }}
    >
      <div style={{ fontWeight: 600, marginBottom: 4 }}>{plan.name}</div>
      <div style={{ fontSize: 22, fontWeight: 700, color: "#f5f5f5" }}>
        {priceNum === 0 ? "Free" : `$${priceNum.toFixed(2)}${interval}`}
      </div>
      {!isActive && onSelect && (
        <button
          onClick={() => onSelect(plan.id)}
          style={{
            marginTop: 12,
            width: "100%",
            padding: "6px 12px",
            background: "#ffffff",
            color: "#000000",
            border: "none",
            borderRadius: 6,
            cursor: "pointer",
            fontSize: 13,
          }}
        >
          Select
        </button>
      )}
      {isActive && (
        <div
          style={{
            marginTop: 12,
            fontSize: 12,
            color: "#e8e8e8",
            fontWeight: 500,
          }}
        >
          ✓ Current Plan
        </div>
      )}
    </div>
  );
}

export function ArcenEmbed({
  accessToken,
  componentId,
  baseUrl = "",
  className,
  style,
  onPlanChange,
}: ArcenEmbedProps) {
  const [data, setData] = useState<ComponentRenderData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!accessToken || !componentId) return;

    fetch(`${baseUrl}/api/v1/components/${componentId}/render`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json() as Promise<{ data: ComponentRenderData }>;
      })
      .then(({ data: d }) => {
        setData(d);
        setError(null);
      })
      .catch((err: unknown) => {
        setError(
          err instanceof Error ? err.message : "Failed to load component",
        );
      })
      .finally(() => setLoading(false));
  }, [accessToken, componentId, baseUrl]);

  const design = data?.component.design ?? {};
  const elements = data?.component.elements ?? [];

  const containerStyle: React.CSSProperties = {
    fontFamily: design.fontFamily ?? "system-ui, sans-serif",
    fontSize: design.fontSize ? `${design.fontSize}px` : "14px",
    color: design.fontColor ?? "#f5f5f5",
    ...style,
  };

  if (loading) {
    return (
      <div
        className={className}
        style={{
          ...containerStyle,
          padding: 24,
          textAlign: "center",
          color: "#888888",
        }}
      >
        Loading...
      </div>
    );
  }

  if (error || !data) {
    return (
      <div
        className={className}
        style={{ ...containerStyle, padding: 24, color: "#ef4444" }}
      >
        {error ?? "Component not available"}
      </div>
    );
  }

  return (
    <div className={className} style={containerStyle}>
      {elements.map((element, i) => {
        switch (element.type) {
          case "planManager":
            return (
              <div key={i} style={{ marginBottom: 24 }}>
                <h3
                  style={{
                    fontWeight: 600,
                    marginBottom: 12,
                    fontSize: "1.1em",
                  }}
                >
                  Current Plan
                </h3>
                {data.activePlan ? (
                  <div
                    style={{
                      padding: 16,
                      background:
                        design.backgroundColor ?? "rgba(255,255,255,0.04)",
                      borderRadius: design.borderRadius ?? 8,
                    }}
                  >
                    <div style={{ fontWeight: 700, fontSize: "1.1em" }}>
                      {data.activePlan.name}
                    </div>
                    <div style={{ color: "#888888", fontSize: 13 }}>
                      {parseFloat(data.activePlan.price) === 0
                        ? "Free"
                        : `$${data.activePlan.price}`}
                    </div>
                  </div>
                ) : (
                  <div style={{ color: "#888888" }}>No active plan</div>
                )}
              </div>
            );

          case "meteredFeatures":
            return (
              <div key={i} style={{ marginBottom: 24 }}>
                <h3
                  style={{
                    fontWeight: 600,
                    marginBottom: 12,
                    fontSize: "1.1em",
                  }}
                >
                  Usage
                </h3>
                {data.usage.length === 0 ? (
                  <div style={{ color: "#888888", fontSize: 13 }}>
                    No metered features
                  </div>
                ) : (
                  data.usage.map((u) => (
                    <MeteredFeatureBar
                      key={u.featureKey}
                      name={u.name}
                      used={u.used}
                      unitPlural={u.unitSingular}
                    />
                  ))
                )}
              </div>
            );

          case "includedFeatures":
            return (
              <div key={i} style={{ marginBottom: 24 }}>
                <h3
                  style={{
                    fontWeight: 600,
                    marginBottom: 12,
                    fontSize: "1.1em",
                  }}
                >
                  Features
                </h3>
                <div
                  style={{ display: "flex", flexDirection: "column", gap: 8 }}
                >
                  {data.entitlements
                    .filter((e) => e.value)
                    .map((e) => (
                      <div
                        key={e.featureKey}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 8,
                          fontSize: 13,
                        }}
                      >
                        <span style={{ color: "#22c55e" }}>✓</span>
                        <span>{e.name}</span>
                      </div>
                    ))}
                </div>
              </div>
            );

          case "plansTable":
            return (
              <div key={i} style={{ marginBottom: 24 }}>
                <h3
                  style={{
                    fontWeight: 600,
                    marginBottom: 12,
                    fontSize: "1.1em",
                  }}
                >
                  Plans
                </h3>
                <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
                  {data.plans.map((plan) => (
                    <PlanCard
                      key={plan.id}
                      plan={plan}
                      isActive={data.activePlan?.id === plan.id}
                      onSelect={onPlanChange}
                    />
                  ))}
                </div>
              </div>
            );

          default:
            return null;
        }
      })}
    </div>
  );
}
